/* Zero-build standalone fallback. The React TypeScript UI sources remain in ../src.
 * All financial calculations, OCR, contract parsing and decisions happen on the Python backend.
 */
const $=id=>document.getElementById(id);
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const usd=x=>x==null?'N/A':'$'+Number(x).toLocaleString('en-US',{maximumFractionDigits:2});
const percent=x=>x==null?'N/A':Number(x).toLocaleString('en-US',{maximumFractionDigits:2});
const card=(label,value)=>`<div class="card"><small>${esc(label)}</small><strong>${esc(value)}</strong></div>`;
const note=x=>`<p class="note">${esc(x)}</p>`;
const intro=(key,title,desc)=>`<div class="hero"><div class="eyebrow">${esc(key)} · SYNTHETIC / DEMONSTRATION</div><h1>${esc(title)}</h1><p>${esc(desc)}</p></div>`;
const field=(key,value,label)=>`<label>${esc(label||key.replaceAll('_',' '))}<input name="${esc(key)}" type="number" step="any" value="${esc(value)}" required></label>`;
const payload=form=>Object.fromEntries([...new FormData(form).entries()].map(([key,value])=>[key,Number(value)]));
const alertFlags=flags=>(flags||[]).map(f=>`<div class="flag"><strong>${esc(f.severity?.toUpperCase())} · ${esc(f.code)}</strong><p>${esc(f.description)}</p><small>${esc(f.evidence||'')}</small></div>`).join('')||note('No rule-based flags detected. Authenticity and legal completeness remain unverified.');
const state={role:'sme',tab:'overview',snap:null,summary:null,contract:'SUPPLY AGREEMENT — SYNTHETIC SAMPLE\nCustomer: Northern Retail LLC\nTotal consideration: USD 200,000\nPayment 30% advance\nPayment 40% upon delivery\nPayment 30% after acceptance\nTermination: Either party may terminate after written notice.\nChanges to bank account require callback verification.',invoice:'Invoice INV-1188, USD 260,000',lastReview:null,bankToken:''};
const smeTabs=[['overview','Overview'],['analytics','Finance EDA'],['project','Bid simulator'],['contracts','Contracts + OCR'],['workflow','Secure multi-agent'],['funding','Financing'],['green','Green finance'],['evidence','Evidence']];
const bankTabs=[['bank','Reviewer case'],['analytics','Finance EDA'],['contracts','Contract checks'],['green','Green evidence'],['evidence','Audit evidence']];
async function req(url,data){const r=await fetch(url,{method:data===undefined?'GET':'POST',headers:{'Content-Type':'application/json'},body:data===undefined?undefined:JSON.stringify(data)});let json=await r.json();if(!r.ok)throw Error(typeof json.detail==='string'?json.detail:JSON.stringify(json.detail||json));return json;}
function message(s,ok=true){$('notice').innerHTML=`<div class="${ok?'success':'error'}">${esc(s)}</div>`;}
function nav(){ $('nav').innerHTML=(state.role==='bank'?bankTabs:smeTabs).map(([id,title])=>`<button data-tab="${id}" ${state.tab===id?'aria-current="page"':''}>${esc(title)}</button>`).join('');
  $('nav').querySelectorAll('button').forEach(b=>b.onclick=()=>openTab(b.dataset.tab));}
async function refresh(){state.snap=await req('/api/snapshot');renderChat();}
function renderChat(){const messages=state.snap?.chat?.history||[];$('chat').innerHTML=messages.map(x=>`<div class="bubble ${esc(x.role)}"><strong>${esc(x.role==='user'?'You':'Copilot')}</strong><div>${esc(x.text)}</div>${x.citations?.length?`<small>Sources: ${x.citations.map(c=>esc(c.source_id)).join(' · ')}</small>`:''}</div>`).join('');$('chat').scrollTop=$('chat').scrollHeight;}
async function openTab(tab){state.tab=tab;$('notice').textContent='';nav();$('page').innerHTML='<p class="muted">Loading evidence…</p>';
  try{if(tab==='overview')overview();else if(tab==='analytics')await analytics();else if(tab==='project')project();else if(tab==='contracts')contracts();else if(tab==='workflow')workflow();else if(tab==='funding')funding();else if(tab==='bank')await bank();else if(tab==='green')await green();else if(tab==='evidence')evidence();}catch(e){message(e.message,false);}}
function overview(){const k=state.snap.kpis;const weeks=state.snap.forecast.weeks||[];
 $('page').innerHTML=intro('SME FINANCIAL CONTROL','Detect the cash gap before it happens.','Unpaid invoices, supplier deposits and marketing decisions compete for working capital. Diagnose exposure before asking to borrow.')+
 `<div class="grid">${card('Available cash',usd(k.cash_today_usd))}${card('First negative forecast week',k.first_shortfall_week==null?'None':k.first_shortfall_week)}${card('Funding shortfall',usd(k.shortfall_usd))}${card('Cash conversion cycle',k.ccc.ccc+' days')}${card('Fraud emails blocked',k.blocked_fraud_count)}${card('Case state',state.snap.meta.case_state)}</div>`+
 `<section class="panel"><h2>13-week cash forecast</h2><div id="forecast-bars"></div>${note('Cash forecast derives from the existing deterministic forecast engine; assumptions and synthetic data are documented in the README.')}</section>`+
 `<section class="panel"><h2>Reconciliation & verification</h2><div class="scroll"><table><tr><th>Transaction</th><th>Amount</th><th>Matched invoices</th><th>Status</th></tr>${state.snap.reconciliation.rows.slice(0,10).map(x=>`<tr><td>${esc(x.txn_id)}</td><td>${usd(x.amount)}</td><td>${esc(x.matched_invoices.join(', '))}</td><td>${esc(x.status)}</td></tr>`).join('')}</table></div></section>`;
 const mx=Math.max(1,...weeks.map(x=>Math.abs(x.closing)));$('forecast-bars').innerHTML=weeks.map((x,i)=>`<div class="chart-line"><span>Week ${i+1}</span><div class="track"><div class="fill" style="width:${Math.max(1,Math.abs(x.closing)/mx*100)}%;background:${x.closing<0?'var(--bad)':'var(--gold)'}"></div></div><span>${usd(x.closing)}</span></div>`).join('');}
async function analytics(){const d=state.summary||await req('/api/analytics/summary');state.summary=d;
const scenario={marketing_increase_pct:25,receipts_delayed_pct:10,new_loan_usd:0,loan_apr_pct:15,horizon_months:3,minimum_reserve_usd:20000};
 $('page').innerHTML=intro('FINANCIAL ANALYTICS','EDA + financial indicators','Server-calculated health metrics, monthly cost trends and interactive cash simulations.')+
 `<section class="panel"><h2>Financial health ratios</h2><div class="grid">${Object.entries(d.ratios).map(([k,v])=>card(k.replaceAll('_',' '),v==null?'N/A':percent(v))).join('')}</div>${note(d.definitions.dscr_proxy)}</section>`+
 `<section class="panel"><h2>12-month EDA · income / expenses / marketing</h2><div class="scroll"><table><tr><th>Month</th><th>Revenue</th><th>Expenses</th><th>Marketing</th><th>Payroll</th></tr>${d.eda.monthly.map(m=>`<tr><td>${esc(m.month)}</td><td>${usd(m.revenue)}</td><td>${usd(m.expenses)}</td><td>${usd(m.marketing)}</td><td>${usd(m.payroll)}</td></tr>`).join('')}</table></div>${note('Statistical expense outliers: '+(d.eda.expense_outliers.map(x=>x.month).join(', ')||'none above 2σ.'))}</section>`+
 `<section class="panel"><h2>Marketing impact and borrowing scenarios</h2><form id="scenario-form"><div class="inputs">${Object.entries(scenario).map(([k,v])=>field(k,v)).join('')}</div><div class="actions"><button type="submit">Calculate scenario</button></div></form><div id="scenario-out"></div></section>`;
 $('scenario-form').onsubmit=async e=>{e.preventDefault();try{const r=await req('/api/analytics/scenario',{data:payload(e.target)});$('scenario-out').innerHTML=`<div class="grid">${card('Baseline closing cash',usd(r.baseline_ending_cash_usd))}${card('Scenario closing cash',usd(r.scenario_ending_cash_usd))}${card('Lowest cash',usd(r.minimum_cash_usd))}</div><p class="${r.reserve_breach?'warn':'good'}">Cash reserve: ${r.reserve_breach?'BREACHED':'Not breached'}</p>${r.schedule.map(x=>`<div class="chart-line"><span>Month ${x.month}</span><div class="track"><div class="fill" style="width:${Math.min(100,Math.max(1,x.closing_cash_usd/Math.max(1,r.baseline_ending_cash_usd)*100))}%"></div></div><span>${usd(x.closing_cash_usd)}</span></div>`).join('')}${r.limitations.map(note).join('')}`;}catch(e){message(e.message,false)}};}
function project(){let d={contract_value_usd:200000,upfront_cost_usd:110000,remaining_cost_usd:55000,available_cash_usd:60000,minimum_reserve_usd:15000,advance_payment_pct:20,stress_cost_overrun_pct:15,loan_apr_pct:15,financing_days:90,workforce_required_hours:400,workforce_available_hours:300,outsourced_hourly_cost_usd:25};
 $('page').innerHTML=intro('PROJECT FINANCING','Can this SME afford the next bid?','Assess initial cash requirements and a payment-delay / cost-overrun stress scenario without making an automated bid decision.')+
 `<section class="panel"><h2>Contract & project assumptions</h2><form id="project-form"><div class="inputs">${Object.entries(d).map(([k,v])=>field(k,v)).join('')}</div><div class="actions"><button type="submit">Assess financial feasibility</button></div></form><div id="project-out"></div></section>`;
 $('project-form').onsubmit=async e=>{e.preventDefault();try{const x=await req('/api/projects/assess',{data:payload(e.target)});$('project-out').innerHTML=`<div class="grid">${card('Initial funding gap',usd(x.initial_funding_gap_usd))}${card('Stress funding gap',usd(x.stress_gap_if_advance_delayed_and_cost_overruns_usd))}${card('Indicative project margin',x.estimated_margin_pct+'%')}${card('Team hours gap',x.workforce_readiness.uncovered_team_hours)}${card('Outsourcing cost',usd(x.workforce_readiness.indicative_outsourcing_cost_usd))}</div>${x.limitations.map(note).join('')}`;}catch(e){message(e.message,false)}};}
function contracts(){ $('page').innerHTML=intro('CONTRACT INTELLIGENCE','Contracts that explain financing risk.','Upload locally processed PDFs/images, compare invoice amounts, highlight suspect clauses and prepare an unsigned agreement draft.')+
 `<section class="panel"><h2>1 · OCR, extract and flag clauses</h2><label class="muted">Upload PDF / PNG / JPG / TXT (max 5 MB, 10 PDF pages)<input id="contract-upload" type="file" accept=".txt,.pdf,.png,.jpg,.jpeg"/></label><div class="actions"><button id="contract-review">Review contract</button><button id="invoice-compare" class="secondary">Compare invoice</button></div><textarea id="contract-text" rows="10"></textarea><h3>Corresponding invoice text</h3><textarea id="invoice-text" rows="3"></textarea><div id="contract-out"></div></section>`+
 `<section class="panel"><h2>2 · Template-based contract drafting</h2><form id="draft-form"><div class="inputs"><label>Type<select name="contract_type"><option>supply</option><option>services</option><option>construction</option></select></label><label>Supplier<input name="supplier" value="Binh Duong Timberworks (synthetic)"/></label><label>Customer<input name="customer" value="Northern Retail (synthetic)"/></label><label>Amount (USD)<input name="amount" type="number" value="200000"/></label><label>Scope<input name="scope" value="Supply verified goods under purchase order"/></label><label>Governing law<input name="governing_law" value="To be confirmed by counsel"/></label></div><div class="actions"><button type="submit">Generate unsigned draft</button><button type="button" id="save-draft" class="secondary">Save .txt draft</button><button type="button" id="save-docx" class="secondary">Export unsigned .docx</button></div></form><textarea id="draft-out" rows="18" placeholder="Draft appears here" readonly></textarea>${note('The draft is not legally reviewed or signed; edit and have qualified counsel review the document before use.')}</section>`;
 $('contract-text').value=state.contract;$('invoice-text').value=state.invoice;
 $('contract-text').oninput=e=>state.contract=e.target.value;$('invoice-text').oninput=e=>state.invoice=e.target.value;
 $('contract-upload').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{const form=new FormData();form.append('file',f);const r=await fetch('/api/contracts/extract-upload',{method:'POST',body:form});const d=await r.json();if(!r.ok)throw Error(d.detail||'Could not extract document');$('contract-text').value=d.text;state.contract=d.text;message('Local extraction complete ('+d.method+'). Please verify all values.');}catch(err){message(err.message,false)}};
 $('contract-review').onclick=async()=>{try{const d=await req('/api/contracts/analyze',{text:state.contract});state.lastReview=d;$('contract-out').innerHTML=`<div class="grid">${card('Review flags',d.risk_signal_count)}${card('Payment sum',d.extracted.payment_percentage_sum==null?'not found':d.extracted.payment_percentage_sum+'%')}${card('Detected amounts',d.extracted.amounts_usd.map(usd).join(' · ')||'not found')}</div>${alertFlags(d.flags)}${d.limitations.map(note).join('')}`;}catch(e){message(e.message,false)}};
 $('invoice-compare').onclick=async()=>{try{const d=await req('/api/contracts/reconcile',{data:{contract_text:state.contract,invoice_text:state.invoice}});$('contract-out').innerHTML=`<div class="grid">${card('Contract amounts',d.contract_amounts_usd.map(usd).join(', '))}${card('Invoice amounts',d.invoice_amounts_usd.map(usd).join(', '))}${card('Amount mismatch',d.amount_mismatch?'FLAGGED':'not detected')}</div>${alertFlags(d.flags)}${note(d.limitations)}`;}catch(e){message(e.message,false)}};
 $('draft-form').onsubmit=async e=>{e.preventDefault();const p=Object.fromEntries(new FormData(e.target).entries());p.amount=Number(p.amount);try{const r=await req('/api/contracts/draft',{data:p});$('draft-out').value=r.draft;message('Unsigned draft generated. Qualified legal review required.');}catch(e){message(e.message,false)}};
 $('save-draft').onclick=()=>{const text=$('draft-out').value;if(!text)return message('Generate a draft first.',false);let u=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'}));let a=document.createElement('a');a.href=u;a.download='CashBridge_unsigned_contract_draft.txt';a.click();URL.revokeObjectURL(u)};
 $('save-docx').onclick=async()=>{const f=$('draft-form');const data=Object.fromEntries(new FormData(f).entries());data.amount=Number(data.amount);
   try{const r=await fetch('/api/contracts/draft-docx',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({data})});
     if(!r.ok){const x=await r.json();throw Error(x.detail||'Cannot export Word draft')}
     const blob=await r.blob();const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='CashBridge_UNSIGNED_DRAFT.docx';a.click();URL.revokeObjectURL(url);
     message('Unsigned Word draft generated; legal review required.');
   }catch(e){message(e.message,false)}};
}

function workflow(){
 const project={contract_value_usd:200000,upfront_cost_usd:110000,remaining_cost_usd:55000,
   available_cash_usd:60000,minimum_reserve_usd:15000,advance_payment_pct:30,
   stress_cost_overrun_pct:15,loan_apr_pct:15,financing_days:100};
 $('page').innerHTML=intro('POLICY-DRIVEN AGENTIC WORKFLOW','Contract → finance → human review',
   'The chat question is DISPLAY ONLY: it cannot authorize tools. A fixed backend policy runs local contract checks, EDA, project cash flow and financing comparison. No LLM receives company documents.')+
 `<section class="panel"><h2>1 · Choose a verified workflow</h2><form id="workflow-form">
 <label>Authorized workflow<select name="workflow"><option value="contract_to_funding">Contract to funding</option><option value="financial_health">Financial health</option><option value="contract_check">Contract check</option><option value="project_finance">Project finance</option></select></label>
 <label>Question to explain to the human (never used for tool selection)<textarea name="question" rows="2">Can our SME afford this contract without compromising our cash reserve?</textarea></label>
 <p class="muted">Project scenario (synthetic, user must validate)</p><div class="inputs">${Object.entries(project).map(([k,v])=>field(k,v)).join('')}</div>
 <p class="muted">Contract text is taken from the Contracts tab. Financial EDA is synthetic and read-only.</p>
 <div class="actions"><button type="submit">Run approved local workflow</button></div></form><div id="workflow-out"></div></section>
 <section class="panel"><h2>2 · Optional public-topic explainer</h2><p class="muted">Human-facing only. The provider receives a predefined public topic, NEVER your question or company data. Disabled by default; local templates are available offline.</p><form id="concept-form"><label>Public concept<select name="topic"><option value="cash_conversion_cycle">Cash conversion cycle</option><option value="cash_reserve">Protecting cash reserves</option><option value="financing_apr">Financing APR</option><option value="contract_milestones">Contract milestones</option><option value="financial_fraud_signals">Fraud review signals</option><option value="green_investment">Green investment payback</option></select></label><div class="actions"><button type="submit" class="secondary">Explain concept</button></div></form><div id="concept-out"></div></section>
 <section class="panel"><h2>3 · Privacy & execution boundary</h2><p class="muted">OCR, calculations and local buyer-risk ML stay in Python. User questions and uploaded files never reach an LLM provider. A read-only analysis cannot approve credit, send documents, sign contracts or move money.</p></section>`;
 $('concept-form').onsubmit=async e=>{e.preventDefault();try{const topic=new FormData(e.target).get('topic');const r=await req('/api/chat/explain-concept',{topic});$('concept-out').innerHTML=`<p>${esc(r.text)}</p>${note('Mode: '+r.mode+' · Private documents transmitted: NO')}`;}catch(err){message(err.message,false)}};
 $('workflow-form').onsubmit=async e=>{e.preventDefault();const form=e.target;const data=Object.fromEntries(new FormData(form).entries());
 const workflow=data.workflow;const question=String(data.question).trim();
 const inputs={workflow};
 if(['contract_to_funding','contract_check'].includes(workflow))inputs.contract_text=state.contract;
 if(['contract_to_funding','contract_check'].includes(workflow) && state.invoice)inputs.invoice_text=state.invoice;
 if(['contract_to_funding','project_finance'].includes(workflow)){
   inputs.project={};for(const key of Object.keys(project))inputs.project[key]=Number(data[key]);
   inputs.cash_waterfall={contract_value_usd:inputs.project.contract_value_usd,
       available_cash_usd:inputs.project.available_cash_usd,minimum_reserve_usd:inputs.project.minimum_reserve_usd,
       receipts:[{day:0,percentage:30,label:'Advance'},{day:35,percentage:40,label:'Delivery'},{day:100,percentage:30,label:'Acceptance'}],
       costs:[{day:0,amount_usd:inputs.project.upfront_cost_usd,label:'Materials'},{day:35,amount_usd:inputs.project.remaining_cost_usd,label:'Payroll and delivery'}]};
 }
 try{const r=await req('/api/copilot/ask',{question,inputs});
  const trace=r.plan.map(x=>`<li><strong>${esc(x.tool)}</strong> · ${esc(x.source_id)} · ${esc(x.caveat)}</li>`).join('');
  const flags=r.results.contract_review?.risk_signal_count??'N/A';
  const gap=r.results.cash_waterfall?.peak_external_funding_usd;
  const bid=r.results.bid_risk?.initial_funding_gap_usd;
  $('workflow-out').innerHTML=`<h3>Verified analysis</h3><div class="grid">${card('Policy',r.orchestration)}${card('LLM tools allowed',r.llm_tools_enabled?'YES':'NO')}${card('Contract risk flags',flags)}${card('Peak cash gap',gap==null?'N/A':usd(gap))}${card('Bid upfront gap',bid==null?'N/A':usd(bid))}${card('Approval state',r.decision)}</div><p>${esc(r.answer)}</p><h3>Deterministic execution trace</h3><ol class="section-list">${trace}</ol><h3>Human review</h3><ul class="section-list">${r.human_actions.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>${note('Milestone schedule is an editable-code demo assumption; not automatically inferred from the contract. All inputs must be verified by an authorized human.')}`;
 }catch(err){message(err.message,false)}};
}
function funding(){const snap=state.snap;const opts=snap.funding_options;
 $('page').innerHTML=intro('SME CAPITAL FINANCING','Compare borrowing on actual APR.','Factoring, bridging and early-payment discounts are computed by the existing financing engine. Only a Director can authorize pack submission using action-bound OTP.')+
 `<section class="panel"><h2>Financing options</h2><div class="scroll"><table><tr><th>Option</th><th>Amount</th><th>Effective APR</th><th>Status</th><th>Action</th></tr>${opts.map(o=>`<tr><td>${esc(o.name)}</td><td>${usd(o.amount_usd)}</td><td>${o.apr_pct==null?'N/A':o.apr_pct.toFixed(2)+'%'}</td><td>${o.eligible?'Eligible, provisional':esc(o.ineligible_reason||'Not eligible')}</td><td>${o.eligible?`<button class="secondary" data-opt="${esc(o.id)}">Choose</button>`:''}</td></tr>`).join('')}</table></div><div class="actions"><button id="prepare">Prepare funding pack</button><button id="otp" class="secondary">Request OTP</button><input id="otp-code" placeholder="6-digit code" inputmode="numeric" maxlength="6"/><button id="approve">Approve with OTP</button></div><div id="pack-status"></div>${note('Submitting sends data only to the MOCK lender connector; real financing and money transfers are unavailable.')}</section>`;
 $('page').querySelectorAll('[data-opt]').forEach(b=>b.onclick=async()=>{try{state.snap=await req('/api/choose_option',{option_id:b.dataset.opt});message('Selected: '+b.dataset.opt);funding();}catch(e){message(e.message,false)}});
 $('prepare').onclick=async()=>{try{state.snap=await req('/api/prepare_pack',{});$('pack-status').textContent=state.snap.pack.status+' · '+(state.snap.meta.last_error||'');}catch(e){message(e.message,false)}};
 $('otp').onclick=async()=>{try{const r=await req('/api/request_otp',{});$('pack-status').textContent=r.instructions;}catch(e){message(e.message,false)}};
 $('approve').onclick=async()=>{try{const r=await req('/api/approve',{code:$('otp-code').value});state.snap=r.snapshot;$('pack-status').textContent=r.ok?'Submitted to MOCK lender, audit locked':'Approval refused: '+r.error;}catch(e){message(e.message,false)}};}
async function green(){let d=await req('/api/green-finance');$('page').innerHTML=intro('GREEN FUNDING','Prepare evidence for green transition.','Readiness checks and illustrative impact estimates; no green taxonomy certification, KYC decision or bank disbursement.')+
 d.projects.map(p=>`<section class="panel"><h2>${esc(p.name)}</h2><div class="grid">${card('Loan request',usd(p.requested_loan_usd))}${card('Evidence completeness',p.documentation_completeness_pct+'%')}${card('Annual impact (illustrative)',p.illustrative_annual_impact_tco2e==null?'N/A':p.illustrative_annual_impact_tco2e+' tCO2e')}</div><ul class="section-list">${p.evidence.map(x=>`<li>${esc(x.label)} — ${esc(x.status)}</li>`).join('')}</ul><div class="actions"><button data-economics="${esc(p.project_id)}" class="secondary">Estimate payback @ $0.12/kWh</button></div><div id="economics-${esc(p.project_id)}"></div><div class="actions"><button data-green="${esc(p.project_id)}" ${p.review_status==='PENDING_HUMAN_REVIEW'?'disabled':''}>${p.review_status==='PENDING_HUMAN_REVIEW'?'Review pending':'Request human review'}</button></div>${note('Synthetic demo queue only; external bank not contacted.')}</section>`).join('');
 $('page').querySelectorAll('[data-economics]').forEach(b=>b.onclick=async()=>{try{const x=await req('/api/green-finance/economics',{project_id:b.dataset.economics,electricity_price_usd_per_kwh:0.12,annual_opex_usd:1500});$('economics-'+b.dataset.economics).innerHTML=card('Estimated net annual savings',usd(x.estimated_net_savings_usd_per_year))+card('Simple payback',x.simple_payback_years==null?'N/A':x.simple_payback_years+' years')+note(x.limitation);}catch(e){message(e.message,false)}});
 $('page').querySelectorAll('[data-green]').forEach(b=>b.onclick=async()=>{try{await req('/api/green-finance/request-review',{project_id:b.dataset.green});await green();}catch(e){message(e.message,false)}});}
async function bank(){
 if(!state.bankToken){
  $('page').innerHTML=intro('SECURE BANK REVIEWER','Read-only evidence, access controlled by backend',
   'UI role switching is cosmetic. The bank API rejects all unauthenticated requests, even if the user edits the frontend.')+
  `<section class="panel"><h2>Demo reviewer authentication</h2><p class="muted">Configure CASHBRIDGE_BANK_REVIEW_TOKEN on the server (at least 24 characters), then enter it below. Token stays only in this page memory, not in localStorage. This is a single-case synthetic demo gate, not production IAM.</p><form id="bank-login"><label>Reviewer Bearer token<input id="bank-token" type="password" required autocomplete="off" minlength="24" placeholder="Server-configured demo token" /></label><div class="actions"><button>Unlock read-only case</button></div></form></section>`;
  $('bank-login').onsubmit=e=>{e.preventDefault();state.bankToken=$('bank-token').value;bank()};return;
 }
 try{
  const response=await fetch('/api/bank/review',{headers:{'Authorization':'Bearer '+state.bankToken}});
  if(!response.ok){const d=await response.json();state.bankToken='';message(typeof d.detail==='string'?d.detail:'Unauthorized bank reviewer access',false);return bank()}
  const d=await response.json();
  $('page').innerHTML=intro('BANK REVIEWER · TOKEN-GATED','Source-labelled underwriting evidence',
    'Read-only synthetic case. Authentication is server-side; token lives only in volatile browser memory. No automated lending decision.')+
  `<div class="actions"><button id="bank-lock" class="secondary">Lock reviewer view</button></div>`+
  `<div class="grid">${card('Case ID',d.case_id)}${card('Audit chain',d.evidence.audit_chain_ok?'Verified internally':'BROKEN')}${card('Invoice registry blocks',d.evidence.invoice_registry_blocks)}</div>`+
  `<section class="panel"><h2>SME financial metrics</h2><div class="grid">${Object.entries(d.financial_ratios).map(([k,v])=>card(k.replaceAll('_',' '),v??'N/A')).join('')}</div></section>`+
  `<section class="panel"><h2>Contract risk review</h2>${d.evidence.document_review?alertFlags(d.evidence.document_review.flags):note('No contract has been reviewed in this demo session.')}</section>`+
  `<section class="panel"><h2>Human lender review</h2><ul class="section-list">${d.review_checklist.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>${note(d.notice)}</section>`;
  $('bank-lock').onclick=()=>{state.bankToken='';bank()};
 }catch(e){state.bankToken='';message(e.message,false)}
}
function evidence(){const x=state.snap.evidence;$('page').innerHTML=intro('CONTROL & EVIDENCE','Trust is a verifiable workflow.','Tamper-evident logs, invoice registry, blocked instructions and OTP approval steps are traceable.')+
 `<div class="grid">${card('Audit chain verification',x.chain_ok?'Valid':'FAILED')}${card('Audit log rows',x.lines_checked)}${card('Registry blocks',x.registry_blocks.length)}</div>`+
 `<section class="panel"><h2>Latest audit actions</h2><div class="scroll"><table><tr><th>#</th><th>Tool</th><th>Tier</th><th>Decision</th></tr>${x.audit_tail.slice(-25).reverse().map(a=>`<tr><td>${a.seq}</td><td>${esc(a.tool)}</td><td>${esc(a.tier)}</td><td>${esc(a.decision)}</td></tr>`).join('')}</table></div><div class="actions"><button id="audit-check">Verify chain again</button></div></section>`;
 $('audit-check').onclick=async()=>{try{let r=await req('/api/verify_chain',{});message(r.ok?'Audit chain verification passed':'Audit chain broken; investigate!',r.ok);}catch(e){message(e.message,false)}};}
async function start(){try{await refresh();nav();openTab('overview');}catch(e){message('Start the Python backend (`make run`): '+e.message,false)}}
$('role').onchange=e=>{state.bankToken='';state.role=e.target.value;openTab(state.role==='bank'?'bank':'overview')};
$('reset').onclick=async()=>{state.bankToken='';try{state.snap=await req('/api/reset_demo',{});state.lastReview=null;state.summary=null;renderChat();await openTab(state.role==='bank'?'bank':'overview');message('Synthetic session reset.');}catch(e){message(e.message,false)}};
$('chat-form').onsubmit=async e=>{e.preventDefault();const t=$('chat-input').value.trim();if(!t)return;try{await req('/api/ask_cfo',{text:t});$('chat-input').value='';await refresh();}catch(e){message(e.message,false)}};
start();
